// @vitest-environment node
//
// The icon set (t32-e22): every icon or manifest file that index.html or the web
// manifest names exists in public/, and each PNG and ICO really has the pixel
// sizes it is declared with. The files are generated by
// scripts/icons/build-icons.py from branding/icon/mark.json and committed; this
// test is what notices a renamed file, a missing size or a stale declaration.
// Admin branding (t32-admin §10.6) serves its overrides at these same paths.

import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const PUBLIC = fileURLToPath(new URL('../public/', import.meta.url));
const INDEX_HTML = fileURLToPath(new URL('../index.html', import.meta.url));

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];

function bytes(rel: string): Uint8Array {
  return new Uint8Array(readFileSync(PUBLIC + rel));
}

function isPng(b: Uint8Array, at = 0): boolean {
  return PNG_SIGNATURE.every((v, i) => b[at + i] === v);
}

/** Width and height from a PNG's IHDR chunk, which always starts at byte 8. */
function pngSize(b: Uint8Array, at = 0): string {
  if (!isPng(b, at)) throw new Error('not a PNG');
  const view = new DataView(b.buffer, b.byteOffset + at);
  if (String.fromCharCode(...b.subarray(at + 12, at + 16)) !== 'IHDR') throw new Error('no IHDR');
  return `${view.getUint32(16)}x${view.getUint32(20)}`;
}

/** Every image in an ICO: the size its directory entry states, and the size of
 *  the embedded image itself (PNG IHDR, or the BMP header's width and half-height). */
function icoEntries(b: Uint8Array): { stated: string; actual: string }[] {
  const view = new DataView(b.buffer, b.byteOffset);
  if (view.getUint16(0, true) !== 0 || view.getUint16(2, true) !== 1) throw new Error('not an ICO');
  const count = view.getUint16(4, true);
  const out: { stated: string; actual: string }[] = [];
  for (let i = 0; i < count; i++) {
    const e = 6 + i * 16;
    const w = b[e] === 0 ? 256 : b[e];
    const h = b[e + 1] === 0 ? 256 : b[e + 1];
    const offset = view.getUint32(e + 12, true);
    const actual = isPng(b, offset)
      ? pngSize(b, offset)
      : `${view.getInt32(offset + 4, true)}x${view.getInt32(offset + 8, true) / 2}`;
    out.push({ stated: `${w}x${h}`, actual });
  }
  return out;
}

interface IconLink {
  rel: string;
  href: string;
  type: string | null;
  sizes: string | null;
}

function iconLinks(): IconLink[] {
  const html = readFileSync(INDEX_HTML, 'utf8');
  const out: IconLink[] = [];
  for (const [tag] of html.matchAll(/<link\b[^>]*>/g)) {
    const attr = (name: string): string | null =>
      new RegExp(`\\s${name}="([^"]*)"`).exec(tag)?.[1] ?? null;
    const rel = attr('rel');
    const href = attr('href');
    if (rel && href && /\b(icon|apple-touch-icon|manifest)\b/.test(rel)) {
      out.push({ rel, href, type: attr('type'), sizes: attr('sizes') });
    }
  }
  return out;
}

/** index.html names public files root-absolute (Vite rewrites them against
 *  `base: './'`, so the built page refers to them relatively). */
function publicPath(href: string): string {
  expect(href, `${href} is a root-absolute public path`).toMatch(/^\/[a-z0-9][a-z0-9./-]*$/);
  return href.slice(1);
}

interface ManifestIcon {
  src: string;
  sizes: string;
  type: string;
  purpose?: string;
}

function manifest(): { name: string; short_name: string; theme_color: string; background_color: string; icons: ManifestIcon[] } {
  return JSON.parse(readFileSync(PUBLIC + 'manifest.webmanifest', 'utf8'));
}

describe('index.html icon and manifest links', () => {
  const links = iconLinks();

  it('declares the favicon (SVG and ICO), the apple-touch icon and the manifest', () => {
    expect(links.map((l) => `${l.rel} ${l.href}`).sort()).toEqual([
      'apple-touch-icon /apple-touch-icon.png',
      'icon /favicon.ico',
      'icon /favicon.svg',
      'manifest /manifest.webmanifest',
    ]);
  });

  it('every linked file exists in public/', () => {
    for (const link of links) {
      const rel = publicPath(link.href);
      expect(existsSync(PUBLIC + rel), `public/${rel} exists`).toBe(true);
    }
  });

  it('a declared type matches the file content', () => {
    for (const link of links.filter((l) => l.type)) {
      const b = bytes(publicPath(link.href));
      if (link.type === 'image/svg+xml') expect(new TextDecoder().decode(b)).toMatch(/^<svg\b/);
      else if (link.type === 'image/png') expect(isPng(b)).toBe(true);
      else throw new Error(`unexpected icon type ${link.type}`);
    }
  });

  it('declared PNG sizes match the IHDR', () => {
    for (const link of links.filter((l) => l.href.endsWith('.png'))) {
      expect(link.sizes, `${link.href} states its size`).not.toBeNull();
      expect(pngSize(bytes(publicPath(link.href))), link.href).toBe(link.sizes);
    }
  });

  it('the ICO holds exactly the declared sizes, and each entry is the size it states', () => {
    const ico = links.find((l) => l.href.endsWith('.ico'));
    expect(ico?.sizes).toBeTruthy();
    const entries = icoEntries(bytes(publicPath(ico!.href)));
    for (const e of entries) expect(e.actual, `ICO entry stated ${e.stated}`).toBe(e.stated);
    expect(entries.map((e) => e.stated).sort()).toEqual(ico!.sizes!.split(/\s+/).sort());
  });
});

describe('manifest.webmanifest', () => {
  const m = manifest();

  it('names the app and uses the near-black field colour', () => {
    expect(m.name).toBe('Mailwoman');
    expect(m.short_name).toBe('Mailwoman');
    expect(m.theme_color).toBe('#111111');
    expect(m.background_color).toBe('#111111');
  });

  it('offers 192 and 512 icons for any purpose and a maskable 512', () => {
    const offered = m.icons.map((i) => `${i.sizes} ${i.purpose ?? 'any'}`).sort();
    expect(offered).toEqual(['192x192 any', '512x512 any', '512x512 maskable']);
  });

  it('every icon is a relative path to a PNG of its declared size', () => {
    for (const icon of m.icons) {
      // Relative to the manifest URL, so the set works under MW_BASE_PATH.
      expect(icon.src).toMatch(/^[a-z0-9][a-z0-9./-]*\.png$/);
      expect(icon.type).toBe('image/png');
      expect(existsSync(PUBLIC + icon.src), `public/${icon.src} exists`).toBe(true);
      expect(pngSize(bytes(icon.src)), icon.src).toBe(icon.sizes);
    }
  });
});
